sub:assertion {
  <https://w3id.org/delphi/resource/claim/composite-never-beat-its-strongest-term>
    a delphi:Claim ;
    rdfs:label "On the primary ranking endpoint P1, the design scorer's composite rank_score has never beaten its own strongest single term, the joint Mahalanobis term used alone." ;
    dct:description "STATUS: this is a measured result, not a proof. It was observed only on the blind held-out run of scorer version 1.3.0, and the evaluation was carried out by an evaluator who built neither the scorer nor the benchmark (SCORER-EVALUATION.md:13); development-set results count for nothing here. WHAT IT DOES NOT ESTABLISH: it says nothing about other scorer versions, nothing about other endpoints, and it does not extend to the secondary endpoints S4 and S5, where the other components of the composite are the ones that matter (SCORER-EVALUATION.md:43). It offers no causal explanation of why the composite fails to improve on the joint term, and it makes no prediction about future data or families beyond the held-out set that was scored." ;
    delphi:hasEvidence <https://w3id.org/delphi/resource/evidence/composite-never-beat-its-strongest-term> .

  <https://w3id.org/delphi/resource/evidence/composite-never-beat-its-strongest-term>
    a delphi:EvidenceItem ;
    rdfs:label "Held-out comparison of rank_score against nearest-neighbour distance and against the joint Mahalanobis term alone" ;
    dct:description "From the blind held-out run, 168 families scored family-out (SCORER-EVALUATION.md:14), version 1.3.0 rank_score beats nearest-neighbour distance on P1 at 0.875, a difference of +0.032 with CI 0.026 to 0.040 (SCORER-EVALUATION.md:33). Against its own joint Mahalanobis term used alone it does not win on P1: difference -0.008, CI -0.020 to 0.002, an interval that spans zero (SCORER-EVALUATION.md:35). Pooled over all held-out items the composite is significantly worse than the joint term alone: -0.007, CI -0.013 to -0.002 (SCORER-EVALUATION.md:36). The joint term alone reaches P1 0.883 and by itself passes all three primary endpoints (SCORER-EVALUATION.md:38). The remaining components earn their place only on secondary endpoints S4 and S5, which the joint term alone fails (SCORER-EVALUATION.md:43). The evaluator built neither scorer nor benchmark (SCORER-EVALUATION.md:13). All locators are in sim-engine/validate/evaluation/SCORER-EVALUATION.md." ;
    schema:additionalProperty sub:pv-nn-diff , sub:pv-vs-joint , sub:pv-all-items , sub:pv-joint-p1 , sub:pv-families , sub:pv-version , sub:pv-secondary .

  sub:pv-nn-diff a schema:PropertyValue ;
    schema:propertyID "rank_score minus nearest-neighbour distance, endpoint P1" ;
    schema:value 0.032 ;
    schema:description "Source: sim-engine/validate/evaluation/SCORER-EVALUATION.md:33. The rank_score of the scorer reaches 0.875 on endpoint P1 and beats nearest-neighbour distance by a difference of 0.032, with a confidence interval of 0.026 to 0.040." .

  sub:pv-vs-joint a schema:PropertyValue ;
    schema:propertyID "rank_score minus joint Mahalanobis term alone, endpoint P1" ;
    schema:value -0.008 ;
    schema:description "Source: sim-engine/validate/evaluation/SCORER-EVALUATION.md:35. The difference is -0.008 with a confidence interval of -0.020 to 0.002; the interval spans zero, so rank_score does not beat its own joint term used alone on P1." .

  sub:pv-all-items a schema:PropertyValue ;
    schema:propertyID "composite minus joint term alone, all held-out items" ;
    schema:value -0.007 ;
    schema:description "Source: sim-engine/validate/evaluation/SCORER-EVALUATION.md:36. Over all held-out items the composite is significantly worse than the joint term alone: difference -0.007, confidence interval -0.013 to -0.002." .

  sub:pv-joint-p1 a schema:PropertyValue ;
    schema:propertyID "joint Mahalanobis term alone, endpoint P1" ;
    schema:value 0.883 ;
    schema:description "Source: sim-engine/validate/evaluation/SCORER-EVALUATION.md:38. The joint Mahalanobis term used alone reaches 0.883 on P1 and passes all three primary endpoints by itself." .

  sub:pv-families a schema:PropertyValue ;
    schema:propertyID "number of held-out families" ;
    schema:value 168 ;
    schema:description "Source: sim-engine/validate/evaluation/SCORER-EVALUATION.md:14. Every reported number comes from the blind held-out run of each scorer version: 168 held-out families, scored family-out." .

  sub:pv-version a schema:PropertyValue ;
    schema:propertyID "scorer version evaluated" ;
    schema:value "1.3.0" ;
    schema:description "Source: sim-engine/validate/evaluation/SCORER-EVALUATION.md:33. The comparison of rank_score against nearest-neighbour distance concerns scorer version 1.3.0." .

  sub:pv-secondary a schema:PropertyValue ;
    schema:propertyID "secondary endpoints where other components earn their place" ;
    schema:value "S4 and S5" ;
    schema:description "Source: sim-engine/validate/evaluation/SCORER-EVALUATION.md:43. The other components earn their place only on secondary endpoints S4 and S5, which the joint term alone fails." .
}

